def _find_snapshot_globally(
    conn: sqlite3.Connection, snapshot_id: int
) -> sqlite3.Row | None:
    return conn.execute(
        """
        SELECT  s.id, s.version_id, s.row_count, s.rows, s.created_at,
                sv.version AS version_number,
                d.name AS dataset_name
        FROM    snapshots s
        JOIN    schema_versions sv ON sv.id = s.version_id
        JOIN    datasets d ON d.id = sv.dataset_id
        WHERE   s.id = ?
        """,
        (snapshot_id,),
    ).fetchone()


def _canonical_row_text(row: Any) -> str:
    # Object key order is ignored (sort_keys) while array order and value types
    # are preserved (e.g. 1 vs "1" vs 1.0 vs true all differ).
    return json.dumps(row, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def _snapshot_multiset(
    rows: list[dict[str, Any]],
) -> tuple[Counter, dict[str, dict[str, Any]]]:
    counts: Counter = Counter()
    examples: dict[str, dict[str, Any]] = {}
    for row in rows:
        key = _canonical_row_text(row)
        counts[key] += 1
        examples.setdefault(key, row)
    return counts, examples


def _row_multiset_diff(
    from_rows: list[dict[str, Any]],
    to_rows: list[dict[str, Any]],
) -> tuple[list[dict], list[dict]]:
    """Added/removed row multiset entries between two snapshot row lists.

    Shares the exact comparison semantics of the snapshot-id diff: object key
    order is irrelevant, array order and value types matter and duplicate rows
    are counted. Returns the ``added`` (only/more often on the to side) and
    ``removed`` entries, each ``{"row", "count"}`` sorted by the canonical
    JSON text of the row.
    """
    from_counts, from_examples = _snapshot_multiset(from_rows)
    to_counts, to_examples = _snapshot_multiset(to_rows)

    added_keys = sorted(key for key in to_counts if to_counts[key] > from_counts[key])
    removed_keys = sorted(key for key in from_counts if from_counts[key] > to_counts[key])

    added = [
        {"row": to_examples[key], "count": to_counts[key] - from_counts[key]}
        for key in added_keys
    ]
    removed = [
        {"row": from_examples[key], "count": from_counts[key] - to_counts[key]}
        for key in removed_keys
    ]
    return added, removed


def _snapshot_field_sets(
    from_rows: list[dict[str, Any]],
    to_rows: list[dict[str, Any]],
) -> tuple[list[str], list[str]]:
    """Top-level field-name sets of two snapshots.

    A field counts when it appears on at least one row object of the side.
    Names only on the to side are ``fields_added``; names only on the from
    side are ``fields_removed``. Both lists sort by field name ascending.
    """
    from_fields = {name for row in from_rows for name in row}
    to_fields = {name for row in to_rows for name in row}
    return (
        sorted(to_fields - from_fields),
        sorted(from_fields - to_fields),
    )


def diff_snapshots(
    conn: sqlite3.Connection,
    dataset_name: str,
    version_number: int,
    from_snapshot_id: int,
    to_snapshot_id: int,
) -> dict:
    # Validate the path target first so unknown dataset/version stay 404.
    dataset = require_dataset(conn, dataset_name)
    version_row = _require_schema_version(conn, dataset, version_number)

    from_row = _find_snapshot_globally(conn, from_snapshot_id)
    if from_row is None:
        raise NotFoundError(f"Snapshot {from_snapshot_id} does not exist")
    to_row = _find_snapshot_globally(conn, to_snapshot_id)
    if to_row is None:
        raise NotFoundError(f"Snapshot {to_snapshot_id} does not exist")

    for row, snapshot_id in ((from_row, from_snapshot_id), (to_row, to_snapshot_id)):
        if row["version_id"] != version_row["id"]:
            raise RequestInvalidError(
                f"Snapshot {snapshot_id} does not belong to version "
                f"{version_number} of dataset '{dataset_name}'; snapshots can "
                "only be compared within the same dataset and version"
            )

    from_rows = json.loads(from_row["rows"])
    to_rows = json.loads(to_row["rows"])
    added, removed = _row_multiset_diff(from_rows, to_rows)

    return {
        "from_snapshot_id": from_snapshot_id,
        "to_snapshot_id": to_snapshot_id,
        "added": added,
        "removed": removed,
    }


# The only query parameters accepted by the snapshot time diff endpoint.
_SNAPSHOT_AT_DIFF_PARAMETERS = frozenset({"from", "to"})


def _parse_diff_timestamp(raw: str, parameter: str) -> datetime:
    try:
        parsed = datetime.fromisoformat(raw)
    except (TypeError, ValueError) as exc:
        raise RequestInvalidError(
            f"Query parameter '{parameter}' must be an ISO-8601 date-time"
        ) from exc
    # A trailing timezone designator (offset or 'Z') is mandatory.
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        raise RequestInvalidError(
            f"Query parameter '{parameter}' must include a timezone"
        )
    return parsed


def diff_snapshots_at(
    conn: sqlite3.Connection,
    dataset_name: str,
    version_number: int,
    *,
    raw_from: str | None,
    raw_to: str | None,
    from_values: tuple[str, ...] = (),
    to_values: tuple[str, ...] = (),
    query_keys: tuple[str, ...] = (),
    body: bytes = b"",
) -> dict:
    """Read-only row/field diff between the snapshots selected at two times.

    Each side independently selects the newest snapshot whose ``created_at``
    is not later than its own timestamp (the same selection as the bare-row
    time lookup), so the two times may resolve to the same snapshot or the to
    time may be earlier than the from time. The row sets use the exact
    comparison semantics of the snapshot-id diff; the field sets compare the
    top-level field names of the row objects on each side.

    The path dataset/version resolves first (404, ahead of every shape
    check). Any request body bytes (whitespace-only included), an unknown or
    repeated query parameter, a missing/blank, unparseable or timezone-less
    ``from``/``to`` is a 422 checked next. Only afterwards are the snapshots
    selected; a side without a snapshot at or before its time is a 404. The
    comparison reads snapshots and rows and never writes anything.
    """
    dataset = require_dataset(conn, dataset_name)
    version_row = _require_schema_version(conn, dataset, version_number)

    # Any request body bytes are a shape error, including a body that is only
    # whitespace (truthiness, not a strip, so pure-whitespace bytes reject too).
    if body:
        raise RequestInvalidError(
            "The snapshot time diff endpoint does not accept a request body"
        )
    unknown_keys = sorted(set(query_keys) - _SNAPSHOT_AT_DIFF_PARAMETERS)
    if unknown_keys:
        raise RequestInvalidError(
            "Unknown query parameter(s): " + ", ".join(unknown_keys)
        )
    if len(from_values) > 1:
        raise RequestInvalidError(
            "Query parameter 'from' must be provided exactly once"
        )
    if len(to_values) > 1:
        raise RequestInvalidError(
            "Query parameter 'to' must be provided exactly once"
        )
    if raw_from is None or not raw_from:
        raise RequestInvalidError(
            "Query parameter 'from' is required and must be an ISO-8601 date-time"
        )
    if raw_to is None or not raw_to:
        raise RequestInvalidError(
            "Query parameter 'to' is required and must be an ISO-8601 date-time"
        )
    from_target = _parse_diff_timestamp(raw_from, "from")
    to_target = _parse_diff_timestamp(raw_to, "to")

    from_row = _select_snapshot_at(conn, version_row["id"], from_target)
    if from_row is None:
        raise NotFoundError(
            f"No snapshot of version {version_number} of dataset "
            f"'{dataset_name}' exists at or before the 'from' timestamp"
        )
    to_row = _select_snapshot_at(conn, version_row["id"], to_target)
    if to_row is None:
        raise NotFoundError(
            f"No snapshot of version {version_number} of dataset "
            f"'{dataset_name}' exists at or before the 'to' timestamp"
        )

    from_rows = json.loads(from_row["rows"])
    to_rows = json.loads(to_row["rows"])
    added, removed = _row_multiset_diff(from_rows, to_rows)
    fields_added, fields_removed = _snapshot_field_sets(from_rows, to_rows)

    return {
        "from_timestamp": raw_from,
        "to_timestamp": raw_to,
        "from_snapshot_id": from_row["id"],
        "to_snapshot_id": to_row["id"],
        "added": added,
        "removed": removed,
        "fields_added": fields_added,
        "fields_removed": fields_removed,
    }


# Exact fields accepted by the masked time-diff request body.
_SNAPSHOT_AT_DIFF_MASKED_FIELDS = frozenset({"role", "from", "to"})


def _parse_snapshot_at_diff_masked_body(
    body: bytes,
) -> tuple[str, str, str]:
    """Validate and parse a raw masked time-diff request body.

    The body must be a JSON object carrying exactly ``role`` (a string that is
    non-empty after trimming whitespace), ``from`` and ``to`` (each an ISO-8601
    date-time carrying a timezone). Returns the trimmed role and the two raw
    timestamp strings (echoed verbatim in the response). Every structural
    problem is a 422.
    """
    if not body.strip():
        raise RequestInvalidError("A JSON request body is required")
    try:
        payload = json.loads(body)
    except (json.JSONDecodeError, UnicodeDecodeError) as exc:
        raise RequestInvalidError("Request body is not valid JSON") from exc
    if not isinstance(payload, dict):
        raise RequestInvalidError("Request body must be a JSON object")

    extra_keys = sorted(set(payload) - _SNAPSHOT_AT_DIFF_MASKED_FIELDS)
    if extra_keys:
        raise RequestInvalidError(
            "Unknown field(s): " + ", ".join(extra_keys)
        )
    if "role" not in payload:
        raise RequestInvalidError("'role' is required")
    if "from" not in payload:
        raise RequestInvalidError("'from' is required")
    if "to" not in payload:
        raise RequestInvalidError("'to' is required")

    raw_role = payload["role"]
    if not isinstance(raw_role, str):
        raise RequestInvalidError("'role' must be a string")
    clean_role = raw_role.strip()
    if not clean_role:
        raise RequestInvalidError("'role' must not be empty")

    raw_timestamps = {}
    for key in ("from", "to"):
        raw = payload[key]
        if not isinstance(raw, str):
            raise RequestInvalidError(
                f"'{key}' must be an ISO-8601 date-time with a timezone"
            )

"""Application errors rendered as stable JSON error responses."""

from __future__ import annotations


class APIError(Exception):
    def __init__(self, status_code: int, code: str, message: str) -> None:
        self.status_code = status_code
        self.code = code
        self.message = message
        super().__init__(message)


class NotFoundError(APIError):
    """A referenced dataset, schema version or field does not exist (404)."""

    def __init__(self, message: str) -> None:
        super().__init__(404, "not_found", message)


class ConflictError(APIError):
    """The request conflicts with already stored state (409)."""

    def __init__(self, message: str) -> None:
        super().__init__(409, "conflict", message)


class RequestInvalidError(APIError):
    """The request is structurally or semantically invalid (422)."""

    def __init__(self, message: str) -> None:
        super().__init__(422, "validation_error", message)

def test_at_diff_document_is_compact_with_fixed_key_order_and_newline(
    client: TestClient,
) -> None:
    create_dataset_and_version(client)
    first = make_snapshot(client, [{"id": 1}])
    time.sleep(0.01)
    second = make_snapshot(client, [{"id": 1}, {"id": 2, "name": "x"}])

    to_value = _future(second["created_at"])
    response = client.get(
        AT_DIFF, params={"from": first["created_at"], "to": to_value}
    )
    assert response.status_code == 200
    body = response.json()
    expected = json.dumps(body, separators=(",", ":"), ensure_ascii=False) + "\n"
    assert response.text == expected
    assert response.text.endswith("\n")
    assert not response.text.endswith("\n\n")
    # Key order is fixed regardless of how the row objects serialize.
    assert response.text.index("from_timestamp") < response.text.index(
        "to_timestamp"
    )
    assert response.text.index("to_snapshot_id") < response.text.index("added")
    assert response.text.index("removed") < response.text.index("fields_added")
    assert response.text.index("fields_added") < response.text.index(
        "fields_removed"
    )


def test_at_diff_accepts_z_and_numeric_offsets(client: TestClient) -> None:
    create_dataset_and_version(client)
    snapshot = make_snapshot(client, [{"id": 1}])
    stored = datetime.fromisoformat(snapshot["created_at"])
    future = stored + timedelta(hours=2)

    z_value = future.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")
    z_response = client.get(
        AT_DIFF, params={"from": z_value, "to": z_value}
    )
    assert z_response.status_code == 200, z_response.text
    assert z_response.json()["from_snapshot_id"] == snapshot["id"]
    # The submitted value is echoed verbatim.
    assert z_response.json()["from_timestamp"] == z_value

    offset_value = future.astimezone(
        timezone(timedelta(hours=5, minutes=30))
    ).isoformat()
    offset_response = client.get(
        AT_DIFF, params={"from": offset_value, "to": offset_value}
    )
    assert offset_response.status_code == 200, offset_response.text
    assert offset_response.json()["to_snapshot_id"] == snapshot["id"]


def test_at_diff_no_snapshot_at_or_before_either_time_is_404(
    client: TestClient,
) -> None:
    create_dataset_and_version(client)
    snapshot = make_snapshot(client, [{"id": 1}])
    before = (
        datetime.fromisoformat(snapshot["created_at"]) - timedelta(seconds=1)
    ).isoformat()
    future = _future(snapshot["created_at"])

    missing_from = client.get(
        AT_DIFF, params={"from": before, "to": future}
    )
    assert missing_from.status_code == 404
    assert missing_from.json()["error"] == "not_found"

    missing_to = client.get(
        AT_DIFF, params={"from": future, "to": before}
    )
    assert missing_to.status_code == 404
    assert missing_to.json()["error"] == "not_found"

    # A version with no snapshots at all cannot serve either side.
    create_dataset_and_version(client, "empty")
    assert client.get(
        "/datasets/empty/versions/1/snapshots/at/diff",
        params={
            "from": "2030-01-01T00:00:00Z",
            "to": "2031-01-01T00:00:00Z",
        },
    ).status_code == 404


def test_at_diff_unknown_dataset_or_version_is_404_before_shape_checks(
    client: TestClient,
) -> None:
    # 404 precedes even missing/invalid parameters and extra query keys.
    assert client.get(
        "/datasets/ghost/versions/1/snapshots/at/diff"
    ).status_code == 404
    create_dataset_and_version(client)
    malformed = client.get(
        "/datasets/ghost/versions/1/snapshots/at/diff",
        params={"from": "not-a-time", "bogus": "1"},
    )
    assert malformed.status_code == 404
    assert client.get(
        "/datasets/orders/versions/7/snapshots/at/diff",
        params={
            "from": "2030-01-01T00:00:00Z",
            "to": "2031-01-01T00:00:00Z",
        },
    ).status_code == 404


def test_at_diff_requires_both_timestamps(client: TestClient) -> None:
    create_dataset_and_version(client)
    valid = "2030-01-01T00:00:00Z"

    for params in ({}, {"from": valid}, {"to": valid}):
        response = client.get(AT_DIFF, params=params)
        assert response.status_code == 422, params
        assert response.json()["error"] == "validation_error"
        assert set(response.json()) == {"error", "detail"}

    # Blank values are missing values.

