    conn: sqlite3.Connection,
    snapshot_row: sqlite3.Row,
) -> tuple[list[str], list[str]]:
    """Canonical row texts and sorted field names of one snapshot.

    The maintained cache record is used directly when it is present and its
    document matches the snapshot's stored content fingerprint; a missing or
    inconsistent record falls back to a fresh computation from the currently
    persisted rows. Both routes yield exactly the same basis, so a diff is
    byte-identical either way.
    """
    cache_row = conn.execute(
        "SELECT row_canons, field_names FROM snapshot_diff_cache "
        "WHERE snapshot_id = ?",
        (snapshot_row["id"],),
    ).fetchone()
    if cache_row is not None:
        row_canons = json.loads(cache_row["row_canons"])
        if _snapshot_cache_document_hash(row_canons) == snapshot_row["content_hash"]:
            return row_canons, json.loads(cache_row["field_names"])

    rows = json.loads(snapshot_row["rows"])
    return _snapshot_cache_payload(rows)

